enum Role {
  CUSTOMER
  SUPPORT
  BILLING
  ADMIN
  // A limited-access staff member with hand-picked page/tool grants (see
  // StaffGrant) rather than a fixed bundle of areas. Deliberately NOT named
  // "STAFF" — isStaff() in lib/rbac.ts already means SUPPORT|BILLING|ADMIN in
  // ~8 call sites, and a same-named role would silently read as included
  // there when it isn't. EMPLOYEE gets zero admin-area access by default;
  // every area it can reach comes from an explicit StaffGrant row.
  EMPLOYEE
}
