35	    34	  // CONTROLLED, deliberately — same reason AddSshKeyForm below is. React 19
36	    35	  // resets uncontrolled fields on every `<form action={fn}>` submit, and this
37	    36	  // form has a REACHABLE server rejection: `changePassword` returns
38	    37	  // "Current password is incorrect." (lib/actions-account.ts). Uncontrolled,
39	    38	  // that mistake wiped BOTH fields — including the new password the customer had
40	    39	  // carefully typed — forcing a full retype. Cleared only on a submit that came
41	    40	  // back without an error, watching the pending edge because the action returns
42	    41	  // `{}` for success, indistinguishable from its initial value.
43	    42	  const [current, setCurrent] = useState("");
44	    43	  const [next, setNext] = useState("");
45	    44	  const wasPending = useRef(false);
46	    45	  useEffect(() => {
47	    46	    if (wasPending.current && !pending && !state?.error) {
48	    47	      setCurrent("");
49	    48	      setNext("");
50	    49	    }
51	    50	    wasPending.current = pending;
52	    51	  }, [pending, state]);
53	    52	  return (
54	    53	    <form action={action} className="space-y-4">
