446	   312	export async function resolveCloudflareToken(user: {
447	   313	  id: string;
448	   314	  cloudflareTokenEnc: string | null;
449	   315	}): Promise<{ token?: string; error?: string; needsReconnect?: boolean }> {
450	   316	  const stored = readStoredCloudflare(user.cloudflareTokenEnc);
451	   317	  if (!stored) return { error: CF_NOT_CONNECTED };
452	   318	  if (stored.kind === "token") return { token: stored.token };
453	   319	
454	   320	  const { creds } = stored;
455	   321	  const expired =
456	   322	    typeof creds.expiresAt === "number" && creds.expiresAt > 0
457	   323	      ? Date.now() > creds.expiresAt - REFRESH_SKEW_MS
458	   324	      : false;
