717	   136	/**
718	   137	 * The caller's address, for use as a rate-limit key. NEVER attacker-controlled.
719	   138	 *
720	   139	 * ── THIS IS THE ONLY DEFINITION ──────────────────────────────────────────────
721	   140	 *
722	   141	 * There were two. This one owned the trusted-hop knob; `trustedClientIp` in
723	   142	 * app/api/_lib/client-ip.ts owned IP-format validation and `::ffff:`/port
724	   143	 * normalisation. Each was correct about something the other got wrong, they were
725	   144	 * written days apart from the same incident, and a reader had no way to know
726	   145	 * which one their call site should use. A second definition of an existing thing
727	   146	 * is this repo's most common defect class and it caused two production bugs in
728	   147	 * one week, so the two have been merged here and `trustedClientIp` is now an
729	   148	 * alias for this function — same code, two names, because ~15 route handlers
730	   149	 * import it under the second one.
731	   150	 *
732	   151	 * Accepts a `Request` as well as a headers object so route handlers and server
733	   152	 * actions call the same function rather than each growing a wrapper.
734	   153	 *
735	   154	 * WHY THIS IS NOT `xff.split(",")[0]`, which is what every call site used to do
736	   155	 * (and what two route handlers still described in a comment as "the real
737	   156	 * client"). nginx forwards the header as:
738	   157	 *
739	   158	 *     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
740	   159	 *
741	   160	 * and `$proxy_add_x_forwarded_for` expands to `$http_x_forwarded_for,
742	   161	 * $remote_addr` — it APPENDS the peer it actually saw to whatever the client
743	   162	 * sent. So the header this app receives is:
744	   163	 *
745	   164	 *     <anything the client typed>, <the client's real address>
746	   165	 *
747	   166	 * The LEFTMOST entry is therefore not the client, it is a free-text field the
748	   167	 * client filled in. Reading it made every limiter keyed on "the IP" evadable by
749	   168	 * sending a different fake value each request — and that is not a theoretical
750	   169	 * grading of a header, it was measured: 25 requests through the real nginx with a
751	   170	 * rotating `X-Forwarded-For` never once tripped a limit that a fixed value trips
752	   171	 * on the 21st. The same expression keyed the login throttle, so the lockout that
753	   172	 * is supposed to stop password AND 2FA guessing against a named account stopped
754	   173	 * nothing. It also keyed the row `POST /api/track` stores as a visitor's IP, so
755	   174	 * the address in the admin visitor log is whatever the visitor chose to claim.
756	   175	 *
757	   176	 * The trustworthy entry is the one NGINX appended: the last one. Everything to
758	   177	 * its left is client-authored and is discarded. `x-real-ip` (set by the same
759	   178	 * vhosts with `proxy_set_header X-Real-IP $remote_addr`, which REPLACES rather
760	   179	 * than appends) is an equally sound second source and is used when no
761	   180	 * X-Forwarded-For arrives at all.
762	   181	 *
763	   182	 * Accepts anything with a `.get()` — `await headers()` from a server action,
764	   183	 * `req.headers`, or the `Request` itself — so there is ONE definition of "who is
765	   184	 * calling" rather than a copy per call site that can drift.
766	   185	 *
767	   186	 * Every candidate is VALIDATED as an IP before it is returned. A header that is
768	   187	 * not an address is not an identity, and letting one through means an attacker
769	   188	 * picks their own bucket name by sending garbage — the same defeat as reading
770	   189	 * the first hop, one step removed. When nothing checks out the caller falls into
771	   190	 * the shared `UNKNOWN_IP` bucket, which is conservative rather than private.
772	   191	 *
773	   192	 * DEPLOYMENT COUPLING: correct for exactly `TRUSTED_PROXY_HOPS` reverse proxies
774	   193	 * in front of the app. If a CDN is ever added, raise that env var; the fix is
775	   194	 * never to go back to reading the leftmost hop.
776	   195	 */
777	   196	export function clientIp(source: ClientIpSource): string {
778	   197	  const h = headersOf(source);
779	   198	  const hops = (h.get("x-forwarded-for") ?? "")
780	   199	    .split(",")
781	   200	    .map((s) => s.trim())
782	   201	    .filter(Boolean);
783	   202	  if (hops.length > 0) {
784	   203	    // Walk back past the proxies we run. Clamped at 0 so a misconfigured hop
785	   204	    // count degrades to "the leftmost entry" instead of throwing, and keep
786	   205	    // walking left while the entry is not a valid address — a junk value at the
787	   206	    // trusted position must not become a bucket key of its own.
788	   207	    for (let i = Math.max(0, hops.length - TRUSTED_PROXY_HOPS); i >= 0; i--) {
789	   208	      const candidate = normaliseAddress(hops[i]);
790	   209	      if (net.isIP(candidate) !== 0) return candidate;
791	   210	    }
792	   211	  }
793	   212	  // `x-real-ip` is set with `proxy_set_header X-Real-IP $remote_addr`, which
794	   213	  // REPLACES any client value rather than appending — an equally sound source.
795	   214	  const real = normaliseAddress(h.get("x-real-ip") ?? "");
796	   215	  if (net.isIP(real) !== 0) return real;
797	   216	  return UNKNOWN_IP;
798	   217	}
