/** Cookie the register page sets when a visitor arrives via a referral link. */
const REF_COOKIE = "nxeon_ref";
/** Cookie the billing CouponField sets when a promo code is applied. */
const COUPON_COOKIE = "nxeon_coupon";

/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
async function uniqueReferralCode(): Promise<string> {
  for (let i = 0; i < 6; i++) {
    const code = generateReferralCode();
    const clash = await db.user.findUnique({ where: { referralCode: code } });
    if (!clash) return code;
  }
  // Extremely unlikely; fall back to a longer code.
  return generateReferralCode(12);
}

// Pure extraction, see lib/audit.ts — kept as a local alias so this file's ~19
// internal call sites don't need renaming.
const audit = recordAudit;

/**
 * Grant the configured signup free credit to a freshly-registered user, once.
 * No-op when the amount is 0 or the account already has signup credit.
 *
 * PRIVATE ON PURPOSE. This used to be an export of lib/actions-growth.ts — a
 * `"use server"` file — which made "credit an arbitrary `userId`" a public
 * network endpoint whose only defence was a guard that inspected request
 * headers. It has exactly one caller, `register` below, and a function with one
 * in-process caller has no business being an endpoint at all. Keeping it here,
 * unexported, is the same reasoning that moved `safeNext` and
 * `verifyTotpForUser` out of `"use server"` files.
 *
 * It also removes a live fragility: the old guard resolved the acting account
 * from the session, and `register` calls this immediately after minting that
 * session, so the grant's success depended on request-scoped session state
 * settling mid-action. Nothing about "did this new account already get its
 * welcome credit?" needs the session — `signupCreditCents` on the row is the
 * only fact that matters, and it is what makes the grant idempotent.
 */
async function grantSignupCredit(userId: string): Promise<number> {
  // Prefer the admin-editable setting (`signup_free_credit_cents`); fall back to
  // the legacy SIGNUP_FREE_CREDIT_CENTS env default when the setting is unset.
  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
  if (cents <= 0) return 0;
  // Idempotent claim: only ever grants against a row that has no signup credit
  // yet, so a retry (or two concurrent registrations of the same account, which
  // the unique email index already prevents) cannot pay twice.
  const claimed = await db.user.updateMany({
    where: { id: userId, signupCreditCents: 0 },
    data: { balanceCents: { increment: cents }, signupCreditCents: cents },
  });
  if (claimed.count === 0) return 0;
  await db.walletTransaction.create({
    data: { userId, amountCents: cents, description: "Welcome credit" },
  });
  return cents;
}

/**
 * A real bcrypt hash at the SAME cost factor the application uses, computed once
 * at module load, so `login` can spend an identical comparison when the address
 * does not exist. See the note at its use site: without it, a missing account
 * answers ~250ms faster than a wrong password and the login form becomes an
 * account-enumeration oracle.
 *
 * Cost 12 matches `register`'s `bcrypt.hash(password, 12)`. If that ever changes,
 * change it here too or the equaliser stops equalising — `test/auth-lockouts.test.ts`
 * asserts the two agree.
 */
const DUMMY_PASSWORD_HASH = bcrypt.hashSync("nxeon-timing-equaliser", 12);

/** Local sentinel: renewNow's compare-and-swap lost the race (already renewed). */
class AlreadyRenewedError extends Error {
  constructor() {
    super("ALREADY_RENEWED");
    this.name = "AlreadyRenewedError";
  }
}

// Thrown inside the top-up transaction when an atomic coupon claim loses its race
// (limit reached) or a double-claim trips the unique(coupon,user) constraint. The
// message is customer-safe; the caller rolls the whole top-up back and surfaces it.
class CouponClaimError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CouponClaimError";
  }
}

// ---------- Auth ----------

const credsSchema = z.object({
  email: z.string().max(200).email("Enter a valid email address"),
  password: z.string().min(8).max(200),
});

export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
  const parsed = credsSchema
    .extend({
      name: z.string().min(1, "Enter your name").max(100, "Name is too long"),
      password: z
        .string()
        .min(8, "Password must be at least 8 characters")
        .max(200, "Password is too long")
        .regex(/[a-zA-Z]/, "Password must include a letter")
        .regex(/[0-9]/, "Password must include a number"),
    })
    .safeParse({
    // Canonicalise BEFORE validating, so `  Alice@Example.com ` is stored in the
    // one form every lookup will use. See lib/email-normalize.ts.
    email: normalizeEmail(formData.get("email")),
    password: formData.get("password"),
    name: formData.get("name"),
  });
  // Say what is actually wrong. This used to collapse four precise, already
  // written messages into "Enter a valid email, name, and password (min 8
  // chars)." — so a customer whose only problem was a missing digit was told
  // about a length rule their 8-character password already satisfied, and had
  // no way to work out what the form wanted. The deploy path (`payAndDeploy`
  // below, via lib/order.ts) has surfaced the real issue since it was written;
  // this is the same one line.
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Check the form and try again." };
  const { email, password, name } = parsed.data;

  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
  // automated account creation and welcome-credit farming.
  const regIp = clientIp(await headers());
  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };

  const existing = await db.user.findUnique({ where: { email } });
  if (existing) return { error: "An account with that email already exists." };

  // Capture a referral from the `ref` cookie (set by the register page) if the
  // code maps to a real user. Self-referral is impossible here (new account).
  const jar = await cookies();
  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
  let referredById: string | null = null;
  let isPartnerCode = false;
  if (refCode) {
    // Agency/KOL PARTNER codes take precedence over peer-referral codes: a single
    // ?ref= must never pay BOTH a lifetime agency commission AND a one-time peer
    // bonus. If the code is an active partner, it's a partner referral only.
    const partner = await db.referralPartner.findUnique({
      where: { code: refCode },
      select: { status: true },
    });
    if (partner && partner.status === "ACTIVE") {
      isPartnerCode = true;
    } else {
      const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
      if (referrer) referredById = referrer.id;
    }
  }

  const referralCode = await uniqueReferralCode();
  const user = await db.user.create({
    data: {
      email,
      name,
      passwordHash: await bcrypt.hash(password, 12),
      referralCode,
      referredById,
    },
  });
  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
  // KOL/Agency partner program: the SAME `ref` code may instead belong to an
  // agency/creator PARTNER (separate code namespace from peer referral codes). If
  // so, permanently attach this new customer to that partner so every future charge
  // earns them a lifetime commission. Best-effort, never blocks registration.
  try {
    if (isPartnerCode) await attachCustomerToPartnerByCode(user.id, refCode);
  } catch (e) {
    console.error("[register] partner attach failed for", user.id, e);
  }
  await createSession(user.id);
  // Grant signup free credit (no-op unless the configured amount is > 0).
  //
  // Still non-fatal — a failure here must not cost the customer the account they
  // just created — but no longer SILENT. `signup_free_credit_cents` is an
  // admin-editable field that the settings panel reports "Saved." for, and an
  // empty `catch {}` here is exactly how this codebase has repeatedly ended up
  // with a control that reports success and does nothing. If the grant fails,
  // that fact is now in the logs and there is a wallet row to reconcile against.
  try {
    await grantSignupCredit(user.id);
  } catch (e) {
    console.error("[register] signup credit grant failed for", user.id, e);
  }
  jar.delete(REF_COOKIE);
  try {
    const { sendMail, emails } = await import("./mailer");
    const tpl = emails.welcome(name);
    await sendMail({ to: email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
  } catch { /* email is best-effort */ }
  // Server-side Meta CAPI CompleteRegistration. A signup IS a conversion, and the
  // browser pixel (SignupTracker → nxTrack('signup')) only fires when the pixel
  // loads — ad-blockers/iOS silently drop it, which is exactly why Meta shows no
  // real sign-up event today. Firing here too, with a shared event_id the browser
  // reuses, means Meta counts EVERY real signup and dedupes the pair into ONE when
  // the pixel does load. The _fbc/_fbp cookies (set on the ad-landing page — _fbc
  // now first-party via MetaPixelTracker, so it survives an ad-blocked pixel) are
  // the strongest match signals and fix the "low fbc coverage" CAPI warning; email
  // + external_id (hashed in sendMetaConversion) + IP/UA back them up. Best-effort
  // and inert unless the pixel id + CAPI token are set; runs after the account is
  // committed, so tracking can never block or fail a signup.
  let signupEventId = "";
  try {
    const h = await headers();
    const { eventId } = await sendMetaConversion({
      eventName: "CompleteRegistration",
      email,
      externalId: user.id,
      clientIp: clientIp(h),
      userAgent: h.get("user-agent") ?? undefined,
      fbc: jar.get("_fbc")?.value || undefined,
      fbp: jar.get("_fbp")?.value || undefined,
      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/register` : undefined,
    });
    signupEventId = eventId;
  } catch {
    /* tracking is best-effort — the account is already created */
  }
  // `?signup=1` is a one-shot marker read (and immediately stripped) by
  // `SignupTracker` on the dashboard so it can fire the browser-side "signup"
  // conversion. `se` carries the SAME event_id the CAPI event above used, so the
  // browser pixel and the server event dedupe to ONE CompleteRegistration (exactly
  // the Purchase pattern) instead of double-counting. Both are tracking hooks only,
  // never a gate on anything, and any unknown query param is ignored by the page.
  // Send the verification link. Best-effort like the welcome mail and it does
  // NOT block the redirect: signing up and looking around stay open, only
  // buying and provisioning wait on the click (lib/email-verification.ts). If
  // this send fails the account is still usable and still resendable from the
  // portal banner — the customer is never stranded on a screen we control.
  try {
    const { sendVerificationEmail } = await import("./email-verification");
    await sendVerificationEmail(user);
  } catch (e) {
    console.error("[register] verification email failed:", e);
  }
  // Queue a SERVER-SIDE Google Ads conversion for this signup, using the gclid we
  // captured on the ad click. Reliable where the browser gtag is not. Best-effort,
  // idempotent (dedupeKey), and a no-op when the account has no gclid or the Ads
  // API creds aren't configured yet. See lib/google-ads.ts.
  try {
    const { recordAdsConversion } = await import("./google-ads");
    await recordAdsConversion({ kind: "signup", userId: user.id, dedupeKey: `signup:${user.id}` });
  } catch {
    /* tracking is best-effort — the account is already created */
  }
  // Honor `next` (e.g. a partner SSO round-trip back to /sso/authorize) exactly
  // like login() does, via the same safeNext allowlist — an unvalidated redirect
  // target here would be an open redirect. Default stays /dashboard. The
  // signup=1&se= tracking marker is appended either way; SignupTracker only reads
  // it on /dashboard, so a non-dashboard `next` (e.g. the SSO flow) simply won't
  // fire the browser pixel this once — the server-side CAPI/Ads events above
  // already recorded the conversion, so nothing is lost, just the extra pixel.
  const next = safeNext(formData.get("next"));
  const dest = next ?? "/dashboard";
  const marker = `signup=1${signupEventId ? `&se=${encodeURIComponent(signupEventId)}` : ""}`;
  redirect(`${dest}${dest.includes("?") ? "&" : "?"}${marker}`);
}

export async function login(
  prev: any,
  formData: FormData,
): Promise<{ error?: string; needs2fa?: boolean }> {
  const parsed = credsSchema.safeParse({
    // Same canonical form the account was stored under (lib/email-normalize.ts).
    // Without this, signing in as `Alice@Example.com` missed a row stored as
    // `alice@example.com` and reported bad credentials for a correct password.
    email: normalizeEmail(formData.get("email")),
    password: formData.get("password"),
  });
  if (!parsed.success) return { error: "Invalid email or password." };

  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
  //
  // The IP comes from `clientIp` (lib/rate-limit.ts), NEVER from
  // `x-forwarded-for.split(",")[0]`. nginx forwards the header with
  // `$proxy_add_x_forwarded_for`, which APPENDS the peer it saw to whatever the
  // client sent — so the leftmost entry is a free-text field the caller filled
  // in, and keying on it meant an attacker could rotate one header value per
  // request and never bind this limiter at all. That is the limiter standing
  // between a known email address and unlimited password guesses, and (below)
  // unlimited 2FA code guesses once a password is known. See the docblock on
  // `clientIp` for the measurement.
  const rlId = `${parsed.data.email}:${clientIp(await headers())}`;
  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };

  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
  // ALWAYS spend one bcrypt comparison, even when the address does not exist.
  //
  // `!user || !(await bcrypt.compare(...))` short-circuits: with no account, bcrypt
  // never ran. The reply text was correctly identical either way, but the reply
  // TIME was not — bcrypt at cost 12 is ~250ms against a single indexed SELECT, a
  // gap one sample per address is enough to read. That turns the login form into
  // an account-enumeration oracle: "does this person bank here", answered for any
  // address, at scale, without ever guessing a password.
  //
  // It was materially worse while the throttle above was keyed on the
  // caller-supplied first hop of `x-forwarded-for`, because the rate limit that
  // would otherwise cap sampling could itself be stepped around per request. That
  // is fixed, but a defence that only works because another defence works is not
  // one, so the timing is equalised on its own terms.
  //
  // The comparison against DUMMY_HASH is discarded — it exists solely to spend the
  // same ~250ms. Keep the reply string identical to the wrong-password case.
  const passwordOk = user
    ? await bcrypt.compare(parsed.data.password, user.passwordHash)
    : ((await bcrypt.compare(parsed.data.password, DUMMY_PASSWORD_HASH)), false);
  // `!user` is repeated here purely so TypeScript narrows `user` for the code
  // below. It is NOT a short-circuit any more: `passwordOk` above has already
  // spent the bcrypt comparison in both branches, which is the whole point.
  if (!user || !passwordOk) {
    return { error: "Invalid email or password." };
  }
  if (user.suspended) return { error: "This account is suspended." };

  // Two-factor challenge, if enabled on the account.
  if (user.totpEnabled) {
    const code = String(formData.get("code") ?? "").trim();
    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
    if (!(await verifyTotpForUser(user.id, code))) {
      return { error: "Invalid 2FA code.", needs2fa: true };
    }
  }

  resetRateLimit(`login:${rlId}`);
  await audit(user.id, "user.login");
  await createSession(user.id);
  // Land where they were HEADING, not on a generic dashboard.
  //
  // Public CTAs like "Migrate free →" send a logged-out visitor into
  // /dashboard/..., which bounces to /login and — until now — discarded what they
  // clicked. They signed in and arrived somewhere unrelated, with no route back to
  // the thing they wanted. Seven CTAs did this, the worst being "Contact support"
  // on the PUBLIC help page, where a prospect met a login wall instead of /contact.
  //
  // `safeNext` only ever returns a path on THIS site (see its definition): an
  // open redirect on a login form is a phishing primitive, so an absolute URL, a
  // protocol-relative `//evil.test` or anything that is not a single-slash path is
  // discarded rather than sanitised.
  const next = safeNext(formData.get("next"));
  redirect(next ?? roleHome(user.role));
}

export async function logout() {
  await destroySession();
  redirect("/login");
}

